css:
.topics-container {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 1.5rem;
            margin-top: 2rem;
        }

        .topic-card {
            background: white;
            border-radius: 1rem;
            padding: 1.5rem;
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
            transition: all 0.3s ease;
            cursor: pointer;
            height: 100%;
        }

        .topic-card:hover {
            transform: translateY(-4px);
            box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1);
        }

        .topic-icon {
            font-size: 1.5rem;
            margin-bottom: 1rem;
            color: var(--accent-blue);
        }

        .topic-title {
            font-size: 1.125rem;
            font-weight: 600;
            color: #1F2937;
            margin-bottom: 0.5rem;
        }

        .topic-description {
            color: #6B7280;
            font-size: 0.875rem;
            line-height: 1.25rem;
            margin-bottom: 1rem;
        }

        .objectives-list {
            list-style: none;
            padding: 0;
            margin: 0;
            font-size: 0.875rem;
            color: #4B5563;
        }

        .objectives-list li {
            display: flex;
            align-items: start;
            gap: 0.5rem;
            margin-bottom: 0.5rem;
        }

        .objectives-list li i {
            color: var(--accent-blue);
            margin-top: 0.25rem;
        }

        /* Modal Styles */
        .modal-overlay {
            display: none;
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(0, 0, 0, 0.5);
            z-index: 50;
            backdrop-filter: blur(4px);
        }

        .modal {
            display: none;
            position: fixed;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            background: white;
            padding: 2rem;
            border-radius: 1rem;
            width: 90%;
            max-width: 600px;
            max-height: 80vh;
            overflow-y: auto;
            z-index: 51;
            box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1);
        }

        .modal-header {
            display: flex;
            justify-content: space-between;
            align-items: start;
            margin-bottom: 1.5rem;
        }

        .modal-title-section {
            flex: 1;
        }

        .modal-title {
            font-size: 1.25rem;
            font-weight: 600;
            color: #1F2937;
            margin-bottom: 0.5rem;
        }

        .modal-subtitle {
            font-size: 0.875rem;
            color: #6B7280;
        }

        .close-modal {
            background: none;
            border: none;
            font-size: 1.5rem;
            color: #6B7280;
            cursor: pointer;
            padding: 0.5rem;
            margin: -0.5rem;
            transition: color 0.2s;
        }

        .close-modal:hover {
            color: #1F2937;
        }

        .subtopics-list {
            list-style: none;
            padding: 0;
        }

        .subtopic-item {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 1rem;
            border-bottom: 1px solid #E5E7EB;
            transition: background-color 0.2s;
        }

        .subtopic-item:last-child {
            border-bottom: none;
        }

        .subtopic-item:hover {
            background: #F9FAFB;
        }

        .subtopic-content {
            flex: 1;
        }

        .subtopic-title {
            font-weight: 500;
            color: #1F2937;
            margin-bottom: 0.25rem;
        }

        .subtopic-description {
            font-size: 0.875rem;
            color: #6B7280;
        }

        .start-learning-btn {
            background: #4F46E5;
            color: white;
            padding: 0.5rem 1rem;
            border-radius: 0.5rem;
            font-size: 0.875rem;
            transition: all 0.2s;
            white-space: nowrap;
            display: flex;
            align-items: center;
            gap: 0.5rem;
        }

        .start-learning-btn:hover {
            background: #4338CA;
            transform: translateY(-1px);
        }

        .progress-bar {
            height: 4px;
            background: #E5E7EB;
            border-radius: 2px;
            margin-top: 1rem;
            overflow: hidden;
        }

        .progress-fill {
            height: 100%;
            background: var(--accent-blue);
            width: 0%;
            transition: width 0.3s ease;
        }
